            to { transform: translateY(0); opacity: 1; }
        }

        .fade-in {
            animation: fadeIn 0.5s ease forwards;
        }

        .slide-up {
            animation:slideUp 0.5s ease forwards;
        }
    </style>
</head>
<body>
    <div id="game-container">
        <div id="bg-layer"></div>
        <div id="character-layer">
            <img class="character" id="char1" src="" alt="">
        </div>
        <div id="dialog-container">
            <div id="name-box" class="slide-up">名字</div>
            <div id="dialog-box" class="slide-up">对话内容</div>
        </div>
        <div id="menu-bar">
            <button class="menu-btn" onclick="toggleAuto()">自动</button>
            <button class="menu-btn" onclick="toggleSkip()">快进</button>
            <button class="menu-btn" onclick="saveGame()">存档</button>
            <button class="menu-btn" onclick="loadGame()">读档</button>
        </div>
    </div>
    <script>
        const gameData = {
            scenes: [
                {
                    bg: 'https://files.catbox.moe/54ptt4.jpg',

                    character: 'https://files.catbox.moe/djrq5y.png',
                    name: '小白子',
                    text: '你好呀，我是本卡的作者小白子哦，dc名是砂狼白子，这段动画是关于本卡的一些注意事项和使用说明哦'
                },
                {
                    bg: 'https://files.catbox.moe/54ptt4.jpg',

                    character: 'https://files.catbox.moe/djrq5y.png',
                    name: '小白子',
                    text: '本卡完全免费，如果你是花钱玩到本卡的说明你当了冤种被倒钩割韭菜了哦。请动动手指举报一下吧！'
                },
                {
                    bg: 'https://files.catbox.moe/54ptt4.jpg',

                    character: 'https://files.catbox.moe/djrq5y.png',
                    name: '小白子',
                    text: '既然你能完整看到这个界面，说明局部正则和前端助手都已经开启了吧，以防万一请再次自检一下哦'
                },
                {
                    bg: 'https://files.catbox.moe/54ptt4.jpg',

                    character: 'https://files.catbox.moe/djrq5y.png',
                    name: '小白子',
                    text: '那么该交待的都交待完了，点击>开始你的游戏哦'
                },
            ],
            currentScene: 0,
            autoPlay: false,
            skipMode: false
        };

        let isTyping = false;
        let typewriterTimer = null;

        function initGame() {
            loadScene(gameData.currentScene);

            document.addEventListener('click', nextScene);
            document.addEventListener('keydown', (e) => {
                if(e.code === 'Space' || e.code === 'Enter') {
                    nextScene();
                }
            });

            window.addEventListener('resize', () => {
                adjustDialogBox();
            });
        }

        function adjustDialogBox() {
            const dialogBox = document.getElementById('dialog-box');
            const windowHeight = window.innerHeight;
            const maxHeight = Math.min(windowHeight * 0.4, 400);
            dialogBox.style.maxHeight = `${maxHeight}px`;
        }

        function loadScene(index) {
            const scene = gameData.scenes[index];

            const bgLayer = document.getElementById('bg-layer');
            bgLayer.style.backgroundImage = `url(${scene.bg})`;

            const charImg = document.getElementById('char1');
            charImg.src = scene.character;
            charImg.style.opacity = '1';

            const nameBox = document.getElementById('name-box');
            const dialogBox = document.getElementById('dialog-box');

            nameBox.classList.remove('slide-up');
            dialogBox.classList.remove('slide-up');
            void nameBox.offsetWidth;
            void dialogBox.offsetWidth;
            nameBox.classList.add('slide-up');
            dialogBox.classList.add('slide-up');

            nameBox.textContent = scene.name;
            typeWriter(scene.text);

            adjustDialogBox();
        }

        function typeWriter(text) {
            isTyping = true;
            const dialogBox = document.getElementById('dialog-box');
            dialogBox.textContent = '';
            let i = 0;

            function type() {
                if(i < text.length) {
                    if(text.charAt(i) === '\n') {
                        dialogBox.innerHTML += '<br>';
                    } else {
                        dialogBox.textContent += text.charAt(i);
                    }
                    i++;
                    dialogBox.scrollTop = dialogBox.scrollHeight;
                    typewriterTimer = setTimeout(type, 50);
                } else {
                    isTyping = false;
                    if(gameData.autoPlay) {
                        setTimeout(nextScene, 2000);
                    }
                }
            }

            type();
        }

        function nextScene() {
            if(isTyping) {
                clearTimeout(typewriterTimer);
                const currentScene = gameData.scenes[gameData.currentScene];
                const dialogBox = document.getElementById('dialog-box');
                dialogBox.innerHTML = currentScene.text.replace(/\n/g, '<br>');
                dialogBox.scrollTop = dialogBox.scrollHeight;
                isTyping = false;
                return;
            }

            gameData.currentScene++;
            if(gameData.currentScene < gameData.scenes.length) {
                loadScene(gameData.currentScene);
            }
        }

        function toggleAuto() {
            gameData.autoPlay = !gameData.autoPlay;
            const autoBtn = document.querySelector('.menu-btn');
            autoBtn.style.background = gameData.autoPlay ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.8)';

            if(gameData.autoPlay && !isTyping) {
                setTimeout(nextScene, 2000);
            }
        }

        function toggleSkip() {
            gameData.skipMode = !gameData.skipMode;
            const skipBtn = document.querySelectorAll('.menu-btn')[1];
            skipBtn.style.background = gameData.skipMode ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.8)';

            if(gameData.skipMode) {
                const skipInterval = setInterval(() => {
                    if(!gameData.skipMode) {
                        clearInterval(skipInterval);
                        return;
                    }
                    nextScene();
                }, 500);
            }
        }

        function saveGame() {
            const saveData = {
                currentScene: gameData.currentScene,
                autoPlay: gameData.autoPlay,
                skipMode: gameData.skipMode
            };
            localStorage.setItem('galGameSave', JSON.stringify(saveData));
            alert('存档成功！');
        }

        function loadGame() {
            const saveData = localStorage.getItem('galGameSave');
            if(saveData) {
                const data = JSON.parse(saveData);
                gameData.currentScene = data.currentScene;
                gameData.autoPlay = data.autoPlay;
                gameData.skipMode = data.skipMode;
                loadScene(gameData.currentScene);
                alert('读档成功！');
            } else {
                alert('没有找到存档！');
            }
        }

        initGame();
    </script>
</body>
</html>
