            commands.push(`/setvar key=world_openness ${world.society.openness}`);
            commands.push(`/setvar key=magic_level ${world.society.magic_level}`);
            commands.push(`/setvar key=danger_level ${world.society.danger_level}`);

            // 设置关系加成
            if (world.relationship_bonus[gameData.relationship]) {
                commands.push(`/setvar key=relationship_bonus ${world.relationship_bonus[gameData.relationship]}`);
            }

            // 发送选择结果
            commands.push(`/send ${outputText}`);
            commands.push('/trigger');

            // 执行所有命令
            triggerSlash(commands.join('|'));
        }

        // 验证选择
        function validateSelections() {
            if (!window.selectedCharacter) {
                alert('请选择一个角色!');
                return false;
            }
            if (!window.selectedRelationship) {
                alert('请选择初始关系!');
                return false;
            }
            if (!window.selectedAttributes || Object.keys(window.selectedAttributes).length < attributes.length) {
                alert('请设置所有属性值!');
                return false;
            }
            if (!window.selectedWorld) {
                alert('请选择一个世界!');
                return false;
            }
            return true;
        }
    </script>
</body>
</html>
